//! OpenCode's design language as a Rune theme: `@opencode/ui`'s tokens (as the browser resolves
//! them, `assets/theme.json`, regenerated by `tools/theme.mjs`), its fonts and its icon catalog,
//! mapped onto rune-kit's semantic schema. Nothing here is compiled into Rune's core.

#if !os(WASI)
import Foundation
#endif
import Rune
import RuneKit

/// The theme as data: palette, light and dark tokens, computed shadows and numbers.
public let THEME: String = {
    #if !os(WASI)
    let sourceURL = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent()
        .appendingPathComponent("assets/theme.json")
    if let data = try? Data(contentsOf: sourceURL),
       let text = String(data: data, encoding: .utf8)
    {
        return text
    }
    #if SWIFT_PACKAGE && !os(Android)
    if let url = Bundle.module.url(forResource: "theme", withExtension: "json", subdirectory: "assets"),
       let data = try? Data(contentsOf: url),
       let text = String(data: data, encoding: .utf8)
    {
        return text
    }
    #endif
    #endif
    return embeddedOpenCodeThemeJson
}()

/// Inter (variable) and IBM Plex Mono, for `AppSpec.fonts`.
// PORT NOTE: Loaded from bundled `assets/fonts` or `Bundle.module` resources on platforms with filesystem/bundle support; empty on WASI where fonts are supplied by the host/app.
public let FONTS: [[UInt8]] = {
    #if !os(WASI)
    let names = ["InterVariable", "IBMPlexMono-Regular", "IBMPlexMono-Medium"]
    let fontsDir = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent()
        .appendingPathComponent("assets/fonts")
    var loaded: [[UInt8]] = []
    for name in names {
        let sourceURL = fontsDir.appendingPathComponent("\(name).ttf")
        if let data = try? Data(contentsOf: sourceURL) {
            loaded.append([UInt8](data))
            continue
        }
        #if SWIFT_PACKAGE && !os(Android)
        if let url = Bundle.module.url(forResource: name, withExtension: "ttf", subdirectory: "assets/fonts"),
           let data = try? Data(contentsOf: url)
        {
            loaded.append([UInt8](data))
        }
        #endif
    }
    return loaded
    #else
    return []
    #endif
}()

/// `AppSpec.families`: (sans, mono).
public let FAMILIES: (String, String) = ("Inter", "IBM Plex Mono")

private let darkThemeInstance: Theme = {
    switch Theme.fromJson(THEME, true) {
    case .success(let t): return t
    case .failure(let e): preconditionFailure("\(e)")
    }
}()

private let lightThemeInstance: Theme = {
    switch Theme.fromJson(THEME, false) {
    case .success(let t): return t
    case .failure(let e): preconditionFailure("\(e)")
    }
}()

/// The resolved `Rune.Theme` for one appearance (every `--*` colour token by name, without `--`).
/// Translucent tokens resolve for the current blend mode as they are read (`Rune.theme.blendsSrgb()`).
public func theme(_ dark: Bool) -> Theme {
    dark ? darkThemeInstance : lightThemeInstance
}

/// The brand's hot colour for one appearance: ember step 9, for marks like a logo or a
/// highlight that should read as the brand rather than the interactive accent.
public func brand(_ dark: Bool) -> Color {
    ember(dark, 9)
}

/// One step of the ember scale for one appearance, the same colour as the token
/// `ember-dark-<step>` or `ember-light-<step>`. `step` is 1 to 12; anything else traps.
public func ember(_ dark: Bool, _ step: UInt8) -> Color {
    scale("ember", dark, step)
}

/// One step (1 to 12, else traps) of a named colour scale (`"amber"`, `"apple"`, `"blue"`,
/// `"cobalt"`, `"coral"`, `"ember"`, `"gray"`, `"ink"`, `"lilac"`, `"mint"`, `"smoke"`,
/// `"solaris"`, `"yuzu"`): the token `<name>-dark-<step>` or `<name>-light-<step>`. Traps if
/// the theme has no such token.
public func scale(_ name: String, _ dark: Bool, _ step: UInt8) -> Color {
    precondition((1...12).contains(step), "colour scale steps run 1 to 12, got \(step)")
    return theme(dark).color("\(name)-\(dark ? "dark" : "light")-\(step)")
}

// PORT NOTE: Minimal pure-Swift JSON value parser for stripping `"blend"` and reading `"shadows"`
// without requiring `Foundation` (`JSONSerialization`) on WASI.
private enum MiniJson {
    case object([(String, MiniJson)])
    case string(String)
    case raw(String)

    static func parse(_ src: String) -> MiniJson? {
        let bytes = Array(src.utf8)
        var i = 0
        func skipWs() {
            while i < bytes.count {
                let b = bytes[i]
                if b == 0x20 || b == 0x09 || b == 0x0A || b == 0x0D { i += 1 } else { break }
            }
        }
        func parseString() -> String? {
            skipWs()
            guard i < bytes.count, bytes[i] == 0x22 else { return nil }
            i += 1
            var out: [UInt8] = []
            while i < bytes.count {
                let b = bytes[i]
                i += 1
                if b == 0x22 {
                    return String(decoding: out, as: UTF8.self)
                }
                if b == 0x5C, i < bytes.count {
                    let esc = bytes[i]
                    i += 1
                    switch esc {
                    case 0x22, 0x5C, 0x2F: out.append(esc)
                    case 0x6E: out.append(0x0A)
                    case 0x72: out.append(0x0D)
                    case 0x74: out.append(0x09)
                    default: out.append(esc)
                    }
                } else {
                    out.append(b)
                }
            }
            return nil
        }
        func parseValue() -> MiniJson? {
            skipWs()
            guard i < bytes.count else { return nil }
            let b = bytes[i]
            if b == 0x7B {
                i += 1
                var pairs: [(String, MiniJson)] = []
                skipWs()
                if i < bytes.count, bytes[i] == 0x7D {
                    i += 1
                    return .object(pairs)
                }
                while i < bytes.count {
                    guard let k = parseString() else { return nil }
                    skipWs()
                    guard i < bytes.count, bytes[i] == 0x3A else { return nil }
                    i += 1
                    guard let v = parseValue() else { return nil }
                    pairs.append((k, v))
                    skipWs()
                    guard i < bytes.count else { return nil }
                    if bytes[i] == 0x2C {
                        i += 1
                    } else if bytes[i] == 0x7D {
                        i += 1
                        return .object(pairs)
                    } else {
                        return nil
                    }
                }
                return nil
            } else if b == 0x22 {
                return parseString().map(MiniJson.string)
            } else if b == 0x5B {
                let start = i
                var depth = 0
                var inStr = false
                while i < bytes.count {
                    let c = bytes[i]
                    i += 1
                    if inStr {
                        if c == 0x5C { i += 1 }
                        else if c == 0x22 { inStr = false }
                    } else {
                        if c == 0x22 { inStr = true }
                        else if c == 0x5B { depth += 1 }
                        else if c == 0x5D {
                            depth -= 1
                            if depth == 0 {
                                return .raw(String(decoding: bytes[start..<i], as: UTF8.self))
                            }
                        }
                    }
                }
                return nil
            } else {
                let start = i
                while i < bytes.count {
                    let c = bytes[i]
                    if c == 0x2C || c == 0x7D || c == 0x5D || c == 0x20 || c == 0x09 || c == 0x0A || c == 0x0D {
                        break
                    }
                    i += 1
                }
                guard i > start else { return nil }
                return .raw(String(decoding: bytes[start..<i], as: UTF8.self))
            }
        }
        return parseValue()
    }

    func encode() -> String {
        switch self {
        case .raw(let r):
            return r
        case .string(let s):
            var escaped = "\""
            for ch in s {
                switch ch {
                case "\"": escaped.append("\\\"")
                case "\\": escaped.append("\\\\")
                case "\n": escaped.append("\\n")
                case "\r": escaped.append("\\r")
                case "\t": escaped.append("\\t")
                default: escaped.append(ch)
                }
            }
            escaped.append("\"")
            return escaped
        case .object(let pairs):
            let body = pairs.map { k, v in "\(MiniJson.string(k).encode()):\(v.encode())" }.joined(separator: ",")
            return "{\(body)}"
        }
    }

    subscript(key: String) -> MiniJson? {
        guard case .object(let pairs) = self else { return nil }
        return pairs.first(where: { $0.0 == key })?.1
    }

    var stringValue: String? {
        if case .string(let s) = self { return s }
        return nil
    }
}

private let parsedThemeJson: MiniJson = {
    guard let root = MiniJson.parse(THEME) else {
        preconditionFailure("theme.json")
    }
    return root
}()

private func loadRawTheme(_ dark: Bool) -> Theme {
    guard case .object(let pairs) = parsedThemeJson else {
        preconditionFailure("theme object")
    }
    let stripped = MiniJson.object(pairs.filter { $0.0 != "blend" }).encode()
    switch Theme.fromJson(stripped, dark) {
    case .success(let t): return t
    case .failure(let e): preconditionFailure("\(e)")
    }
}

private let rawDarkThemeInstance: Theme = loadRawTheme(true)
private let rawLightThemeInstance: Theme = loadRawTheme(false)

/// The theme without sRGB re-solving: translucent tokens keep their authored alpha.
func rawTheme(_ dark: Bool) -> Theme {
    dark ? rawDarkThemeInstance : rawLightThemeInstance
}

private let kitLightLinear: Kit = Rune.theme.withBlend(false) { build(false) }
private let kitLightSrgb: Kit = Rune.theme.withBlend(true) { build(false) }
private let kitDarkLinear: Kit = Rune.theme.withBlend(false) { build(true) }
private let kitDarkSrgb: Kit = Rune.theme.withBlend(true) { build(true) }

/// The kit tokens for one appearance, resolved for the blend mode of the window building the
/// view (`Rune.theme.blendsSrgb()`): translucent tokens as authored when it blends in sRGB,
/// re-solved over `bgBase` when it blends in linear light. Get it in the view rather than
/// keeping it across a `Tx.setSrgbBlend`.
public func kit(_ dark: Bool) -> Kit {
    let srgb = Rune.theme.blendsSrgb()
    if dark {
        return srgb ? kitDarkSrgb : kitDarkLinear
    } else {
        return srgb ? kitLightSrgb : kitLightLinear
    }
}

/// Inter at a variable weight with the kit's tracking (`-0.04px` at 13, `0.05px` at 11).
private func inter(_ size: Float, _ weight: Float, _ line: Float, _ tracking: Float) -> TextStyle {
    TextStyle.new(size, weight).lh(line).tracking(tracking)
}

public let GLYPHS: Glyphs = {
    var g = glyphs.DEFAULT
    g.copy = icons.COPY
    g.search = icons.MAGNIFYING_GLASS
    g.circleX = icons.CIRCLE_X
    g.triangleDown = icons.FILL_TRIANGLE_DOWN
    g.clear = icons.XMARK_SMALL
    g.close = icons.CLOSE
    return g
}()

private func build(_ dark: Bool) -> Kit {
    let t = theme(dark)
    let rawT = rawTheme(dark)
    func c(_ n: String) -> Color { t.color(n) }
    func v(_ n: String) -> Color { t.color("v2-\(n)") }
    func raw(_ n: String) -> Color { rawT.color("v2-\(n)") }
    func state(_ n: String, _ icon: Color) -> StateColors {
        StateColors(
            bg: v("state-bg-\(n)"),
            fg: v("state-fg-\(n)"),
            border: v("state-border-\(n)"),
            icon: icon
        )
    }
    let blend = v("background-bg-base")
    let solve: (Color) -> Color = { x in Rune.theme.forBlend(x, blend) }

    guard let shadowsObj = parsedThemeJson["shadows"] else {
        preconditionFailure("theme.json")
    }
    let mode = dark ? "dark" : "light"
    let modeShadows = shadowsObj[mode]
    func sh(_ n: String) -> [Shadow] {
        guard let src = modeShadows?[n]?.stringValue else {
            preconditionFailure("theme.json has no \(mode) shadow \(n)")
        }
        return css.boxShadows(src, solve)
    }
    func opaque(_ n: String) -> Color { t.color(n).alpha(1.0) }
    // Tokens some components read but the kit never defines resolve as CSS does: no colour
    // (transparent backgrounds) or the inherited text colour.
    func or(_ n: String, _ fallback: Color) -> Color { t.tryColor(n) ?? fallback }

    let palette = Palette(
        page: c("background-base"),
        bgBase: blend,
        bgDeep: v("background-bg-deep"),
        layer01: v("background-bg-layer-01"),
        layer02: v("background-bg-layer-02"),
        layer03: v("background-bg-layer-03"),
        layer04: v("background-bg-layer-04"),
        bgInverse: v("background-bg-inverse"),
        bgContrast: v("background-bg-contrast"),
        bgButtonNeutral: v("background-bg-button-neutral"),
        bgIconButtonContrast: v("background-bg-icon-button-contrast"),
        bgAccent: v("background-bg-accent"),
        submitHighlight: dark ? raw("alpha-light-60") : raw("alpha-light-20"),
        submitHover: dark ? raw("alpha-dark-8") : raw("overlay-simple-overlay-contrast-hover"),
        submitFg: dark ? v("text-text-inverse") : v("text-text-contrast"),
        submitIcon: dark ? v("icon-icon-inverse") : v("text-text-contrast"),
        textBase: v("text-text-base"),
        textMuted: v("text-text-muted"),
        textFaint: v("text-text-faint"),
        textInverse: v("text-text-inverse"),
        textContrast: v("text-text-contrast"),
        textAccent: v("text-text-accent"),
        iconBase: v("icon-icon-base"),
        iconMuted: v("icon-icon-muted"),
        iconFaint: v("icon-icon-faint"),
        iconInverse: v("icon-icon-inverse"),
        iconContrast: v("icon-icon-contrast"),
        iconAccent: v("icon-icon-accent"),
        borderMuted: v("border-border-muted"),
        borderBase: v("border-border-base"),
        borderStrong: v("border-border-strong"),
        borderFocus: v("border-border-focus"),
        hover: v("overlay-simple-overlay-hover"),
        pressed: v("overlay-simple-overlay-pressed"),
        contrastHover: raw("overlay-simple-overlay-contrast-hover"),
        contrastPressed: raw("overlay-simple-overlay-contrast-pressed"),
        scrim: v("overlay-simple-overlay-scrim"),
        depthTop: raw("overlay-gradient-depth-overlay-depth-top"),
        depthBottom: raw("overlay-gradient-depth-overlay-depth-bot"),
        white: opaque("v2-alpha-light-100"),
        black: opaque("v2-alpha-dark-100"),
        knob: v("grey-200"),
        knobOn: v("grey-300"),
        success: state("success", c("icon-success-active")),
        warning: state("warning", c("icon-warning-active")),
        danger: state("danger", v("state-fg-danger")),
        info: state("info", c("icon-info-active")),
        surfaceBase: c("surface-base"),
        surfaceWeak: c("surface-weak"),
        surfaceHover: or("surface-hover", Color.TRANSPARENT),
        surfaceRaised: c("surface-raised-stronger-non-alpha"),
        surfaceRaisedBase: c("surface-raised-base"),
        surfaceRaisedHover: c("surface-raised-base-hover"),
        surfaceFloat: c("surface-float-base"),
        surfaceDisabled: or("surface-disabled", Color.TRANSPARENT),
        borderWeak: c("border-weak-base"),
        borderHover: c("border-hover"),
        borderActive: c("border-active"),
        borderDisabled: c("border-disabled"),
        textStrong: c("text-strong"),
        textWeak: c("text-weak"),
        textInvertStrong: c("text-invert-strong"),
        iconWeaker: or("icon-weaker", c("text-base")),
        stdBorder: c("border-base"),
        stdIcon: c("icon-base"),
        stdIconInvert: c("icon-invert-base"),
        stdIconStrong: c("icon-strong-base"),
        stdText: c("text-base")
    )

    let elevation = Elevation(
        raised: sh("v2-elevation-raised"),
        floating: sh("v2-elevation-floating"),
        overlay: sh("v2-elevation-overlay"),
        buttonNeutral: sh("v2-elevation-button-neutral"),
        buttonContrast: sh("v2-elevation-button-contrast"),
        elements: sh("v2-elevation-elements"),
        switchOff: sh("v2-elevation-switch-off"),
        switchOn: sh("v2-elevation-switch-on"),
        md: sh("shadow-md"),
        // switch.css, standard appearance: rgba(19, 16, 16, .04/.06/.08).
        knob: css.boxShadows(
            "#1310100a 0px 1px 2px -1px, #1310100f 0px 1px 2px 0px, #13101014 0px 1px 3px 0px",
            solve
        )
    )

    // `line-height-large` is 150%; the older text styles derive their line from it.
    let ty = `Type`(
        ui: inter(13.0, 440.0, 20.0, -0.04),
        uiMedium: inter(13.0, 530.0, 20.0, -0.04),
        uiCompact: inter(13.0, 440.0, 16.0, -0.04),
        small: inter(11.0, 440.0, 12.0, 0.05),
        smallMedium: inter(11.0, 530.0, 12.0, 0.05),
        body: inter(14.0, 400.0, 21.0, 0.0),
        bodyMedium: inter(14.0, 500.0, 21.0, 0.0),
        textSmall: inter(13.0, 400.0, 19.5, 0.0),
        textSmallMedium: inter(13.0, 500.0, 19.5, 0.0),
        textXsmall: inter(12.0, 400.0, 18.0, 0.0),
        textXsmallMedium: inter(12.0, 500.0, 18.0, 0.0),
        mono: TextStyle.new(12.0, 400.0).mono().lh(18.0)
    )

    return Kit(
        dark: dark,
        c: palette,
        elevation: elevation,
        glyph: GLYPHS,
        ty: ty,
        radius: Radius(xs: 2.0, sm: 4.0, md: 6.0, lg: 8.0, xl: 10.0),
        // The web's 85–170 ms ease-outs, as critically damped springs of similar feel.
        motion: Motion(
            control: Spring.new(0.2, 0.0),
            overlay: Spring.new(0.24, 0.0),
            disclosure: Spring.new(0.3, 0.0)
        ),
        blendOver: blend,
        ring: nil,
        invalidText: true
    )
}
